CREATE TABLE IF NOT EXISTS display_campaigns (id bigserial PRIMARY KEY, hospital_id bigint NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE, advertiser_name text NOT NULL, title text NOT NULL, body text, media_type text NOT NULL DEFAULT 'text' CHECK (media_type IN ('text','image','video')), media_url text, click_url text, active boolean NOT NULL DEFAULT true, starts_at timestamp, ends_at timestamp, priority integer NOT NULL DEFAULT 100, monthly_price numeric(12,2) NOT NULL DEFAULT 0, hospital_share_percent numeric(5,2) NOT NULL DEFAULT 60, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now())